import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"惜贤","description":"","frontmatter":{"title":"惜贤","date":"2026-11-24T00:00:00.000Z","seq":52,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"刘向","source_book":"楚辞","prev":{"text":"远逝","link":"/blogs/楚辞/远逝.html"},"next":{"text":"忧苦","link":"/blogs/楚辞/忧苦.html"}},"headers":[],"relativePath":"blogs/楚辞/惜贤.md","filePath":"blogs/楚辞/惜贤.md"}'),o={name:"blogs/楚辞/惜贤.md"};function l(n,a,c,m,z,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="惜贤" tabindex="-1">惜贤 <a class="header-anchor" href="#惜贤" aria-label="Permalink to &quot;惜贤&quot;">​</a></h1><p class="poem-meta">先秦 · 刘向　·　九叹</p><div class="poem"><p class="poem-stanza">览屈氏之离骚兮，心哀哀而怫郁。</p><p class="poem-stanza">声嗷嗷以寂寥兮，顾仆夫之憔悴。</p><p class="poem-stanza">拨谄谀而匡邪兮，切淟涊之流俗。</p><p class="poem-stanza">荡渨涹之奸咎兮，夷蠢蠢之溷浊。</p><p class="poem-stanza">怀芬香而挟蕙兮，佩江蓠之婓婓。</p><p class="poem-stanza">握申椒与杜若兮，冠浮云之峨峨。</p><p class="poem-stanza">登长陵而四望兮，览芷圃之蠡蠡。</p><p class="poem-stanza">游兰皋与蕙林兮，睨玉石之嵾嵯。</p><p class="poem-stanza">扬精华以炫燿兮，芳郁渥而纯美。</p><p class="poem-stanza">结桂树之旖旎兮，纫荃蕙与辛夷。</p><p class="poem-stanza">芳若兹而不御兮，捐林薄而菀死。</p><p class="poem-stanza">驱子侨之奔走兮，申徒狄之赴渊。</p><p class="poem-stanza">若由夷之纯美兮，介子推之隐山。</p><p class="poem-stanza">晋申生之离殃兮，荆和氏之泣血。</p><p class="poem-stanza">吴申胥之抉眼兮，王子比干之横废。</p><p class="poem-stanza">欲卑身而下体兮，心隐恻而不置。</p><p class="poem-stanza">方圜殊而不合兮，钩绳用而异态。</p><p class="poem-stanza">欲俟时于须臾兮，日阴曀其将暮。</p><p class="poem-stanza">时迟迟其日进兮，年忽忽而日度。</p><p class="poem-stanza">妄周容而入世兮，内距闭而不开。</p><p class="poem-stanza">俟时风之清激兮，愈氛雾其如塺。</p><p class="poem-stanza">进雄鸠之耿耿兮，谗介介而蔽之。</p><p class="poem-stanza">默顺风以偃仰兮，尚由由而进之。</p><p class="poem-stanza">心懭悢以冤结兮，情舛错以曼忧。</p><p class="poem-stanza">搴薜荔于山野兮，采撚支于中洲。</p><p class="poem-stanza">望高丘而叹涕兮，悲吸吸而长怀。</p><p class="poem-stanza">孰契契而委栋兮，日晻晻而下颓。</p><p class="poem-stanza">叹曰：</p><p class="poem-stanza">江湘油油长流汩兮，挑揄扬汰荡迅疾兮。</p><p class="poem-stanza">忧心展转愁怫郁兮，冤结未舒长隐忿兮，</p><p class="poem-stanza">丁时逢殃可奈何兮，劳心悁悁涕滂沱兮。</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
